export async function parts(name) {
  const fixed = await import("./parts/fixed.js");
  const chosen = await import(`./parts/${name}.js`);
  const waited = await import("./waits.mjs");
  const again = await import("./parts/fixed.js");
  return [fixed.label, chosen.label, waited.ready, waited.loads, again === fixed, chosen === fixed].join(" ");
}
